SELECT JSON_OBJECT(
  'format_version', 1,
  'checkpoint', ?,
  'captured_at_utc', UTC_TIMESTAMP(6),
  'database', DATABASE(),
  'mysql_version', VERSION(),
  'session_time_zone', @@session.time_zone,
  'event_scheduler', @@global.event_scheduler,
  'products', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id', `id`, 'code', `code`, 'name', `name`, 'unit', `unit`, 'current_stock', `current_stock`, 'minimum_stock', `minimum_stock`, 'status', `status`, 'deleted_at', `deleted_at`, 'deleted_by', `deleted_by`, 'created_at', `created_at`)) FROM `products`), JSON_ARRAY()),
  'transactions', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id', `id`, 'type', `type`, 'date', `date`, 'user_id', `user_id`, 'person_id', `person_id`, 'notes', `notes`, 'total_items', `total_items`, 'status', `status`, 'invalidated_at', `invalidated_at`, 'invalidated_by', `invalidated_by`, 'invalidation_reason', `invalidation_reason`, 'loan_code', `loan_code`, 'loan_status', `loan_status`, 'expected_return_date', `expected_return_date`, 'actual_return_date', `actual_return_date`, 'related_transaction_id', `related_transaction_id`, 'return_type', `return_type`, 'return_notes', `return_notes`, 'created_at', `created_at`)) FROM `transactions`), JSON_ARRAY()),
  'transaction_items', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id', `id`, 'transaction_id', `transaction_id`, 'product_id', `product_id`, 'quantity', `quantity`, 'notes', `notes`, 'status', `status`, 'created_at', `created_at`)) FROM `transaction_items`), JSON_ARRAY()),
  'users', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id', `id`, 'username', `username`, 'rol_id', `rol_id`, 'status', `status`, 'must_change_password', `must_change_password`, 'deleted_at', `deleted_at`, 'deleted_by', `deleted_by`, 'created_at', `created_at`)) FROM `users`), JSON_ARRAY()),
  'roles', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id', `id`, 'nombre', `nombre`, 'descripcion', `descripcion`, 'status', `status`, 'activo', `activo`, 'deleted_at', `deleted_at`, 'deleted_by', `deleted_by`, 'created_at', `created_at`)) FROM `roles`), JSON_ARRAY()),
  'permisos', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id', `id`, 'modulo', `modulo`, 'accion', `accion`, 'descripcion', `descripcion`)) FROM `permisos`), JSON_ARRAY()),
  'rol_permisos', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('rol_id', `rol_id`, 'permiso_id', `permiso_id`)) FROM `rol_permisos`), JSON_ARRAY()),
  'people', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id', `id`, 'status', `status`, 'deleted_at', `deleted_at`, 'deleted_by', `deleted_by`, 'created_at', `created_at`)) FROM `people`), JSON_ARRAY()),
  'audit', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id', `id`, 'user_id', `user_id`, 'action', `action`, 'table_name', `table_name`, 'record_id', `record_id`, 'details', `details`, 'created_at', `created_at`)) FROM `audit`), JSON_ARRAY()),
  'schema_migrations', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('migration_name', `migration_name`, 'applied_at', `applied_at`)) FROM `schema_migrations`), JSON_ARRAY()),
  'schema', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('table',TABLE_NAME,'column',COLUMN_NAME,'type',COLUMN_TYPE,'nullable',IS_NULLABLE)) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()), JSON_ARRAY()),
  'checks', JSON_OBJECT('negative_stock', (SELECT COUNT(*) FROM products WHERE current_stock < 0), 'invalid_quantities', (SELECT COUNT(*) FROM transaction_items WHERE quantity <= 0), 'item_count_mismatch', (SELECT COUNT(*) FROM transactions t WHERE t.total_items <> (SELECT COUNT(*) FROM transaction_items i WHERE i.transaction_id=t.id)), 'active_items_on_invalidated', (SELECT COUNT(*) FROM transaction_items i JOIN transactions t ON t.id=i.transaction_id WHERE t.status='invalidated' AND i.status='active'), 'cancelled_items_on_active', (SELECT COUNT(*) FROM transaction_items i JOIN transactions t ON t.id=i.transaction_id WHERE t.status='active' AND i.status='cancelled'), 'orphan_items', (SELECT COUNT(*) FROM transaction_items i LEFT JOIN transactions t ON t.id=i.transaction_id LEFT JOIN products p ON p.id=i.product_id WHERE t.id IS NULL OR p.id IS NULL), 'active_return_on_invalidated_loan', (SELECT COUNT(*) FROM transactions r JOIN transactions l ON l.id=r.related_transaction_id WHERE r.type='in' AND r.status='active' AND l.type='loan' AND l.status<>'active'), 'multiple_active_returns', (SELECT COUNT(*) FROM (SELECT related_transaction_id FROM transactions WHERE type='in' AND status='active' AND related_transaction_id IS NOT NULL GROUP BY related_transaction_id HAVING COUNT(*)>1) d), 'open_loan_with_active_return', (SELECT COUNT(*) FROM transactions l JOIN transactions r ON r.related_transaction_id=l.id WHERE l.type='loan' AND l.status='active' AND l.loan_status IN ('pending','overdue') AND r.type='in' AND r.status='active'), 'closed_loan_without_active_return', (SELECT COUNT(*) FROM transactions l LEFT JOIN transactions r ON r.id=l.related_transaction_id AND r.type='in' AND r.status='active' AND r.related_transaction_id=l.id WHERE l.type='loan' AND l.status='active' AND l.loan_status IN ('returned','paid','replaced') AND r.id IS NULL))
)
